import numpy as np,pandas as pd
from alphacrafter.sim.utils import get_account_dict,get_index_daily_data,get_stock_daily_data
u=get_account_dict().get('watch_list',[]) or ['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
fs={}
for s in u:
 d=None
 for fn in (get_index_daily_data,get_stock_daily_data):
  try: d=fn(s,days=3000)
  except Exception: pass
  if d is not None and len(d): break
 if d is not None and len(d):
  x=d[['date','close']].dropna(); x.date=pd.to_datetime(x.date)
  fs[s]=x.drop_duplicates('date').set_index('date').close.sort_index()
p=pd.DataFrame(fs).sort_index().ffill(); r=p.pct_change()
# One-session-lagged 20d return divided by downside deviation; rewards positive trend
# while penalizing assets whose recent risk is concentrated in negative sessions.
down=r.where(r<0,0).pow(2).rolling(20,min_periods=15).mean().pow(.5)
sig=(p.pct_change(20)/down).shift(1).replace([np.inf,-np.inf],np.nan)
for h in [1,5,10,20]:
 f=p.shift(-h)/p-1; vals=[]; dates=[]; ns=[]
 for dt in sig.index:
  z=pd.concat([sig.loc[dt],f.loc[dt]],axis=1).dropna()
  if len(z)>=8:
   q=z.iloc[:,0].corr(z.iloc[:,1],method='spearman')
   if np.isfinite(q): vals.append(q);dates.append(dt);ns.append(len(z))
 a=np.array(vals); print('H',h,'dates',len(a),'avg_n',round(np.mean(ns),2),'IC',round(a.mean(),6),'ICIR',round(a.mean()/a.std(ddof=1)*np.sqrt(len(a)),6),'hit',round((a>0).mean(),4))
 if h==10:
  rk=sig.rank(axis=1,pct=True); t=[]
  for i in range(1,len(rk)):
