   if len(c)>=8:t.append(abs(rk.iloc[i][c]-rk.iloc[i-1][c]).mean())
  print('TURN',round(np.mean(t),6),'COVERAGE',round(sig.notna().sum().sum()/(sig.shape[0]*len(u)),4))
  for lab,a0,b in [('2020-22','2020','2022-12-31'),('2023-25','2023','2025-12-31'),('2026-28','2026','2028-12-31')]:
   q=np.array([vals[i] for i,d in enumerate(dates) if pd.Timestamp(a0)<=d<=pd.Timestamp(b)])
   print('REG',lab,'n',len(q),'IC',round(q.mean(),6),'ICIR',round(q.mean()/q.std(ddof=1)*np.sqrt(len(q)),6) if len(q)>1 else None)
sig.index.name='date'; sig.to_csv('scripts/miner_2_20281023_downside_sharpe20_signal.csv')
print('range',p.index.min(),p.index.max(),'assets',len(fs))

