from scipy.stats import spearmanr
prices={}
for f in glob.glob('../persistent/stock_data/*.csv'):
 s=os.path.basename(f)[:-4]; d=pd.read_csv(f); d.date=pd.to_datetime(d.date); prices[s]=d.sort_values('date').set_index('date').close
c=pd.DataFrame(prices).sort_index(); r=c.pct_change(); vol=r.rolling(20).std();
