r=pd.DataFrame(out,columns=['date','ic','n']).set_index('date'); m=r.ic.mean(); ir=m/r.ic.std(ddof=1)*np.sqrt(252)
print('factor=volnorm_reversal3 dates=%d avg_n=%.2f coverage=%.2f IC=%.6f daily_ICIR=%.6f hit=%.4f'%(len(r),r.n.mean(),r.n.mean()/15,m,ir,(r.ic>0).mean()))
