p=pd.concat(fs,axis=1).sort_index(); r=p.pct_change(); cs=r.median(axis=1); resid=r.sub(cs,axis=0)
# shock-reversal: reverse 5d residual move, normalized by recent idiosyncratic vol
f=-(resid.rolling(5,min_periods=4).sum()/resid.rolling(20,min_periods=12).std()).shift(1); y=p.shift(-10)/p-1
