 if len(z)>=8:
  ics.append(z.iloc[:,0].corr(z.iloc[:,1],method='spearman'));cov.append(len(z)/15)
  q=f.loc[dt].rank(pct=True)
  if prev is not None: turn.append((q-prev).abs().mean())
  prev=q
A=np.array(ics);A=A[np.isfinite(A)]
print('dates',len(A),'avg_cov',np.mean(cov),'IC',A.mean(),'ICIR',A.mean()/A.std(ddof=1),'hit',(A>0).mean(),'turn',np.mean(turn))
for a in np.array_split(A,3):print('regime',len(a),a.mean(),a.mean()/a.std(ddof=1))
