 print('decay',h,'IC %.8f'%pd.Series(oo).mean())
rank=sig.rank(axis=1,pct=True); print('coverage',sig.notna().sum().sum()/(len(px)*len(U)),'turnover',rank.diff().abs().mean(axis=1).dropna().mean(),'breadth<.4',float((breadth<.4).mean()))
